$g=[IO.File]::ReadAllText('C:\claudecode\dark raiders\dark_raiders.html')
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L '(?m)^#root #pausebox > div:has\(> #resumebtn\) > #fbbtn, #root #pausebox > div:has\(> #resumebtn\) > #wnbtn\{ color:var\(--tx-1\); \}$'
$css=@'
/* v31.xx (cw-pausebtn) critic c-31 on the pause box (25, 42, 49 all 3): "three button tiers (56px, 40px, text-only) in one card", "abandon run is bare red text with no box, so it reads as a caption", "feedback and what is new are 40px high, hard to hit with a pad", "report a problem and settings are filled differently". Now: feedback and what is new are 48px high with the same panel fill and line border as the other buttons, and abandon run, end run and return to character selection are 48px buttons with a 1px danger border and danger text, 32px below the stack. Q61 keeps every one of them. */
#root #pausebox > div:has(> #resumebtn) > #fbbtn, #root #pausebox > div:has(> #resumebtn) > #wnbtn{ min-height:var(--btn-h-sm); font-size:var(--fs-label); font-weight:600; letter-spacing:var(--track); background:var(--ui-panel); border-color:var(--ui-line-hi); }
#root #pausebox:not(.asking) > div:has(> #resumebtn) > #abandonbtn, #root #pausebox:not(.asking) > div:has(> #resumebtn) > #arcendbtn, #root #pausebox:not(.asking) > div:has(> #resumebtn) > #charselbtn{ min-height:var(--btn-h-sm); margin-top:var(--sp-4); border:1px solid var(--danger) !important; color:var(--danger) !important; background:transparent; }
'@.Replace("`r",'')
$r1=$a1.TrimEnd("`n")+"`n"+$css.TrimEnd("`n")
$chk=@'
  {v:'VER',what:'Pause box small buttons are 48px high and abandon run is a bordered danger button',
   run:function(){
     var bad=[], f, w, a, cs;
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{
       f=document.getElementById('fbbtn'); w=document.getElementById('wnbtn'); a=document.getElementById('abandonbtn');
       if(!f||!w||!a){ bad.push('pause buttons missing'); }
       else{
         if(parseFloat(getComputedStyle(f).minHeight)<48) bad.push('feedback min height '+getComputedStyle(f).minHeight);
         if(parseFloat(getComputedStyle(w).minHeight)<48) bad.push('what is new min height '+getComputedStyle(w).minHeight);
         cs=getComputedStyle(a);
         if(parseFloat(cs.minHeight)<48) bad.push('abandon min height '+cs.minHeight);
         if(parseFloat(cs.borderTopWidth)<1||cs.borderTopColor==='rgba(0, 0, 0, 0)') bad.push('abandon has no border ('+cs.borderTopWidth+' '+cs.borderTopColor+')');
       }
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{ try{ __topClear(); }catch(_c){} }
     return bad.length?bad.join('; '):null; }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='PAUSE BOX: 48PX SMALL BUTTONS, ABANDON RUN BORDERED'
  why='Critic c-31 (pause box 25, 42, 49 all 3): three button tiers, abandon run bare red text, small buttons 40px.'
  now='Feedback and whats new are 48px with the panel fill, and abandon run, end run and return to character selection are 48px bordered danger buttons.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-pausebtn.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'

